import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long[] stack = new long[(int) n];
        int size = 0;
        for (int i = 0; i < n; i++) {
            long x = a[i];
            boolean alive = true;
            while (alive && x < 0 && size > 0 && stack[size - 1] > 0) {
                if (stack[size - 1] < -x) {
                    size--;
                } else if (stack[size - 1] == -x) {
                    size--;
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) stack[size++] = x;
        }
        StringBuilder sb = new StringBuilder();
        if (size == 0) sb.append("empty");
        for (int i = 0; i < size; i++) sb.append(stack[i]).append(i + 1 < size ? " " : "");
        System.out.println(sb);
    }
}
